mapper.select:
SELECT e.*,
    s.school_name AS school_name,
    g.grade_name AS grade_name,
    (SELECT COUNT(1) FROM exam_subject es WHERE es.exam_id = e.id AND es.deleted = 0) AS subject_count
FROM exam e
LEFT JOIN school s ON s.id = e.school_id
LEFT JOIN grade g ON g.id = e.grade_id
WHERE e.deleted = 0

    AND e.school_id = #{query.schoolId}


    AND e.name LIKE CONCAT('%', #{query.name}, '%')


    AND e.type = #{query.type}


    AND e.academic_year = #{query.academicYear}


    AND e.semester = #{query.semester}


    AND e.grade_id = #{query.gradeId}


    AND e.status = #{query.status}

ORDER BY e.create_time DESC
